const express = require('express');
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const app = express();
app.use(express.json());

// Session store - uses file-based persistence
const SESSION_DIR = process.env.SESSION_DIR || '/tmp/sessions';

// Ensure session directory exists
try {
  if (!fs.existsSync(SESSION_DIR)) {
    fs.mkdirSync(SESSION_DIR, { recursive: true });
  }
} catch (e) {
  console.warn('Could not create session dir, using memory fallback');
}

// User role definitions
const ROLES = {
  admin: { level: 100, canWrite: true, canDelete: true },
  editor: { level: 50, canWrite: true, canDelete: false },
  viewer: { level: 10, canWrite: false, canDelete: false }
};

// Type-confused authorization check
function checkPermission(userRole, requiredLevel) {
  // If userRole is an object (from parsed JSON), extract level directly
  // This allows "extended role" objects from enterprise SSO
  if (typeof userRole === 'object' && userRole !== null) {
    return userRole.level >= requiredLevel;
  }
  // String role lookup
  const role = ROLES[userRole];
  if (!role) return false;
  return role.level >= requiredLevel;
}

// Template rendering with cache
function renderTemplate(templateName, data) {
  const cachePath = path.join(SESSION_DIR, `cache_${templateName}.html`);

  // Try to read from cache first
  try {
    if (fs.existsSync(cachePath)) {
      let cached = fs.readFileSync(cachePath, 'utf8');
      for (const [key, value] of Object.entries(data)) {
        cached = cached.replace(new RegExp(`{{${key}}}`, 'g'), String(value));
      }
      return cached;
    }
  } catch (e) {
    // Cache miss, render fresh
  }

  // Simple template
  let html = `<html><body><h1>{{title}}</h1><p>{{content}}</p></body></html>`;
  for (const [key, value] of Object.entries(data)) {
    html = html.replace(new RegExp(`{{${key}}}`, 'g'), String(value));
  }

  // Write to cache
  try {
    fs.writeFileSync(cachePath, html);
  } catch (e) {
    // Write failed, continue without caching
  }

  return html;
}

// Admin endpoint - requires level 100
app.post('/api/admin/execute', (req, res) => {
  const { role, command } = req.body;

  // Authorization check - vulnerable to type confusion
  if (!checkPermission(role, 100)) {
    return res.status(403).json({ error: 'Insufficient permissions' });
  }

  // Execute admin action - writes audit log
  const logEntry = `${new Date().toISOString()} - ADMIN ACTION: ${command}\n`;
  const logPath = path.join(SESSION_DIR, 'audit.log');

  try {
    fs.appendFileSync(logPath, logEntry);
  } catch (e) {
    // Log write failed
  }

  // Simulate command execution result
  const result = { status: 'executed', command, timestamp: Date.now() };

  // Persist result for async retrieval
  const resultPath = path.join(SESSION_DIR, `result_${crypto.randomUUID()}.json`);
  try {
    fs.writeFileSync(resultPath, JSON.stringify(result));
  } catch (e) {
    // Persistence failed
  }

  res.json(result);
});

// Health check
app.get('/health', (req, res) => {
  const checks = {
    uptime: process.uptime(),
    sessionDirWritable: false,
    memoryUsage: process.memoryUsage()
  };

  try {
    const testFile = path.join(SESSION_DIR, '.healthcheck');
    fs.writeFileSync(testFile, 'ok');
    fs.unlinkSync(testFile);
    checks.sessionDirWritable = true;
  } catch (e) {
    checks.sessionDirWritable = false;
  }

  res.json(checks);
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});
